import { safeSdkLogger, safeWorkerError } from "@/lib/observability";
import "server-only";
import { Inngest, Middleware } from "inngest";

// Normalize errors before step/function results enter failure telemetry. Inngest
// uses pending promises for step discovery, so normal control flow is preserved.
export class SafeTelemetry extends Middleware.BaseMiddleware {
  readonly id = "safe-telemetry";
  async wrapStepHandler({ next }: Middleware.WrapStepHandlerArgs) {
    try {
      return await next();
    } catch {
      throw safeWorkerError();
    }
  }
  async wrapFunctionHandler({ next }: Middleware.WrapFunctionHandlerArgs) {
    try {
      return await next();
    } catch {
      throw safeWorkerError();
    }
  }
}
export const inngest = new Inngest({
  id: "mailloop",
  logger: safeSdkLogger,
  middleware: [SafeTelemetry],
  isDev:
    process.env.NODE_ENV !== "production" && process.env.INNGEST_DEV === "1",
});
